import random
import time
from functools import wraps
from collections import deque

class CircuitBreakerOpen(Exception):
    pass

class CircuitBreaker:
    """Simple failure-rate circuit breaker."""
    def __init__(self, fail_threshold=0.5, window=20, cooldown=10.0):
        self.fail_threshold = fail_threshold
        self.window = window
        self.cooldown = cooldown
        self.results = deque()          # recent True/False (success/fail)
        self.opened_at = 0.0

    def allow(self):
        if self.results and self._fail_rate() >= self.fail_threshold:
            if time.time() - self.opened_at < self.cooldown:
                return False            # OPEN
        return True

    def record(self, success):
        self.results.append(success)
        if len(self.results) > self.window:
            self.results.popleft()
        if not success and self._fail_rate() >= self.fail_threshold:
            self.opened_at = time.time()

    def _fail_rate(self):
        if not self.results:
            return 0.0
        return sum(1 for r in self.results if not r) / len(self.results)

def retry(max_attempts=3, base=0.1, cap=10.0, jitter="full", cb=None):
    """Exponential backoff + jitter + circuit breaker."""
    def deco(fn):
        @wraps(fn)
        def wrapped(*args, **kwargs):
            last_exc = None
            for attempt in range(1, max_attempts + 1):
                if cb and not cb.allow():
                    raise CircuitBreakerOpen("downstream unhealthy")
                try:
                    result = fn(*args, **kwargs)
                    if cb: cb.record(True)
                    return result
                except Exception as e:
                    last_exc = e
                    if cb: cb.record(False)
                    if attempt == max_attempts:
                        break
                    backoff = min(base * (2 ** (attempt - 1)), cap)
                    if jitter == "full":
                        delay = random.uniform(0, backoff)
                    else:  # equal jitter
                        delay = backoff / 2 + random.uniform(0, backoff / 2)
                    time.sleep(delay)
            raise last_exc
        return wrapped
    return deco

# Demo
cb = CircuitBreaker()
flaky = {"calls": 0}

@retry(max_attempts=4, base=0.01, cb=cb)
def call_downstream():
    flaky["calls"] += 1
    if flaky["calls"] < 3:
        raise ConnectionError("transient 503")
    return "OK"

print("result:", call_downstream())   # succeeds on attempt 3
print("fail rate:", cb._fail_rate())
